package com.sistemahospitalar.hospital.service; import com.sistemahospitalar.hospital.model.Quarto; import com.sistemahospitalar.hospital.repository.QuartoRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class QuartoService {private final QuartoRepository repo; public QuartoService(QuartoRepository repo){this.repo=repo;} public List<Quarto> listar(){return repo.findAll();} public Quarto salvar(Quarto q){return repo.save(q);}}
